-- M1 buildings: Town Hall (#24), Housing Tent/Cabin (#28), Tool Rack, hidden power sink. Placeholder art: tinted vanilla chests.
local G = "__colony-bio-logistics__/graphics/"
-- Placeholder art lives in mod/graphics (generated by scripts/gen_art.py). `half` = half collision size in tiles.
local function chest_clone(base, name, art, size, half)
  local e = table.deepcopy(data.raw["container"][base])
  e.name = name
  e.minable = {mining_time = 0.5, result = name}
  e.inventory_size = size
  e.localised_name = {"entity-name." .. name}
  e.localised_description = {"entity-description." .. name}
  e.picture = {filename = G .. art .. ".png", size = half * 2 * 64, scale = 0.5}
  e.icon = G .. "icon-" .. art .. ".png"; e.icon_size = 64; e.icons = nil
  e.collision_box = {{-half + 0.1, -half + 0.1}, {half - 0.1, half - 0.1}}
  e.selection_box = {{-half, -half}, {half, half}}
  e.circuit_connector = nil
  e.fast_replaceable_group = nil
  e.next_upgrade = nil
  return e
end

local function item_of(entity, art, order)
  return {
    type = "item", name = entity.name, icon = G .. "icon-" .. art .. ".png", icon_size = 64,
    subgroup = "storage", order = order, place_result = entity.name, stack_size = 10,
    localised_name = {"entity-name." .. entity.name},
  }
end

local function recipe(name, ingredients, time)
  local ing = {}
  for item, n in pairs(ingredients) do ing[#ing + 1] = {type = "item", name = item, amount = n} end
  return {type = "recipe", name = name, enabled = true, energy_required = time,
    ingredients = ing, results = {{type = "item", name = name, amount = 1}}}
end

local hall = chest_clone("steel-chest", "colony-town-hall", "town-hall", 48, 1.5)
local tent = chest_clone("iron-chest", "colony-housing-tent", "tent", 4, 1)
local cabin = chest_clone("steel-chest", "colony-housing-cabin", "cabin", 6, 1.5)
local forager = chest_clone("iron-chest", "colony-forager-hut", "forager-hut", 4, 1)
local woodcutter = chest_clone("iron-chest", "colony-woodcutter-hut", "woodcutter-hut", 4, 1)
local miner = chest_clone("iron-chest", "colony-miner-hut", "miner-hut", 4, 1)

-- Forage patch: spawned/regrown by the Forager's Hut (see scripts/colony.lua). Visible, harvested by colonists.
local bush = {
  type = "simple-entity", name = "colony-forage-patch", localised_name = {"entity-name.colony-forage-patch"},
  icon = G .. "bush.png", icon_size = 64, flags = {"placeable-neutral", "not-on-map"},
  collision_box = {{-0.3, -0.3}, {0.3, 0.3}}, selection_box = {{-0.5, -0.5}, {0.5, 0.5}},
  picture = {filename = G .. "bush.png", size = 64, scale = 0.7}, render_layer = "object",
}

-- Hidden electric consumer used to detect whether a powered house is on a live network (read sink.energy).
local sink = table.deepcopy(data.raw["electric-energy-interface"]["electric-energy-interface"])
sink.name = "colony-power-sink"
sink.localised_name = {"entity-name.colony-power-sink"}
sink.minable = nil
sink.flags = {"not-on-map", "placeable-off-grid", "not-blueprintable", "not-deconstructable", "hide-alt-info"}
sink.collision_mask = {layers = {}}
sink.selectable_in_game = false
sink.energy_source = {type = "electric", usage_priority = "secondary-input", buffer_capacity = "20kJ", output_flow_limit = "0W"}
sink.energy_production = "0W"
sink.energy_usage = "5kW"
sink.picture = {filename = "__core__/graphics/empty.png", size = 1}
sink.pictures = nil

local function tool(name, icon)
  return {type = "item", name = name, icon = G .. icon, icon_size = 64, subgroup = "tool",
    order = "z[colony]-" .. name, stack_size = 20, localised_name = {"item-name." .. name}}
end

data:extend({
